func EnqueueReferenceClearedIn(ctx context.Context, tx TxInterface, msg *types.ReferenceCleared, delay time.Duration) error {
	var columns []string
	var values []any
	columns = append(columns, `holder_table`)
	values = append(values, msg.HolderTable)
	columns = append(columns, `holder_key`)
	values = append(values, msg.HolderKey)
	columns = append(columns, `target_table`)
	values = append(values, msg.TargetTable)
	columns = append(columns, `target_key`)
	values = append(values, msg.TargetKey)
	columns = append(columns, `role`)
	values = append(values, msg.Role)
	return referenceClearedQueue.insert(ctx, tx, columns, values, delay)
}

// ReferenceClearedQueue claims the messages of the queue ReferenceCleared for a worker. A
// message whose handler fails is due again after 30s, doubled for each
// attempt before, up to 3600s, and is dead after 5 such retries. A done
// message stays 604800s, then Prune removes it.
//
// One message per reference a target's delete cleared, which the build
// fills: the row that held it, the row deleted and the role.
type ReferenceClearedQueue struct {
	pool *pgxpool.Pool
}

// ReferenceClearedQueue returns the queue ReferenceCleared of the database.
func (db *Database) ReferenceClearedQueue() *ReferenceClearedQueue {
	return &ReferenceClearedQueue{pool: db.pool}
}

// ReferenceClearedClaim is a claimed message of ReferenceCleared: its ID, the token of
// the claim, which attempt this is, from 1, and the message.
type ReferenceClearedClaim struct {
	ID      string
	Token   string
	Attempt int
	Message types.ReferenceCleared
}

// Claim claims up to n due messages for lease; a message that does not read
// into its type it fails alone, recording Unreadable and why. Each field
// reads its column as a table's field does.
func (q *ReferenceClearedQueue) Claim(ctx context.Context, n int, lease time.Duration) ([]ReferenceClearedClaim, error) {
	var claims []ReferenceClearedClaim
	err := referenceClearedQueue.claim(ctx, q.pool, n, lease, func(rows pgx.Rows) error {
		var claim ReferenceClearedClaim
		msg := &claim.Message
		if err := rows.Scan(&claim.ID, &claim.Token, &claim.Attempt, &msg.HolderTable, &msg.HolderKey, &msg.TargetTable, &msg.TargetKey, &msg.Role); err != nil {
			return err
		}
		claims = append(claims, claim)
		return nil
	})
	if errors.Is(err, errKeyHeld) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return claims, nil
}

// Complete marks the message id, which token claims, done.
func (q *ReferenceClearedQueue) Complete(ctx context.Context, id, token string) error {
	return referenceClearedQueue.complete(ctx, q.pool, id, token)
}

// Fail records cause on the message id, which token claims, and makes it
// due again after the backoff, doubled for each attempt before and capped at
// the maximum backoff, or dead when its retries are spent. It reports
// whether the message is dead.
func (q *ReferenceClearedQueue) Fail(ctx context.Context, id, token, cause string) (bool, error) {
	return referenceClearedQueue.fail(ctx, q.pool, id, token, cause)
}

// Extend holds the message id, which token claims, for lease from now.
func (q *ReferenceClearedQueue) Extend(ctx context.Context, id, token string, lease time.Duration) error {
	return referenceClearedQueue.extend(ctx, q.pool, id, token, lease)
}

// Release gives the message id, which token claims, back, due at once.
func (q *ReferenceClearedQueue) Release(ctx context.Context, id, token string) error {
	return referenceClearedQueue.release(ctx, q.pool, id, token)
}

// Prune deletes up to limit messages done 604800s ago or more, the oldest
// first, and returns how many it deleted; a worker runs it again while it
// deletes limit. It never deletes a dead message.
func (q *ReferenceClearedQueue) Prune(ctx context.Context, limit int) (int, error) {
	return referenceClearedQueue.prune(ctx, q.pool, limit)
}

// Slot takes one of slots locks named for the queue, which a worker in
// drain mode holds while it runs (D145), so no more than slots of them
// drain the queue at once: it reports false when every one is taken, and
// otherwise returns the function that gives the slot back.
func (q *ReferenceClearedQueue) Slot(ctx context.Context, slots int) (release func(), ok bool, err error) {
	return referenceClearedQueue.slot(ctx, q.pool, slots)
}

// NextDue reports how long until the first ready message that is not due
// yet falls due, by the database's clock, or false when none waits: a
// worker in drain mode that found the queue idle waits for one due within
// its horizon instead of exiting (D145).
func (q *ReferenceClearedQueue) NextDue(ctx context.Context) (time.Duration, bool, error) {
	return referenceClearedQueue.nextDue(ctx, q.pool)
}
